#import "../App/AI/Usage/TFAIUsageStore.h"
static int checks=0;
static void Check(BOOL pass,NSString *name){checks++;if(!pass){fprintf(stderr,"FAIL %s\n",name.UTF8String);exit(1);}}
static NSArray *Read(TFAIUsageStore *store){__block NSArray *result=nil;dispatch_semaphore_t done=dispatch_semaphore_create(0);[store read:^(NSArray *r,NSString *e){result=r;dispatch_semaphore_signal(done);}];Check(dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,10*NSEC_PER_SEC))==0,@"read finishes");return result;}
int main(){@autoreleasepool{
 NSDictionary *chat=TFAINormalizeUsage(@{@"prompt_tokens":@1000,@"completion_tokens":@100,@"prompt_tokens_details":@{@"cached_tokens":@800},@"completion_tokens_details":@{@"reasoning_tokens":@20}},@"chat");Check([chat[@"input"] isEqual:@1000]&&[chat[@"cachedInput"] isEqual:@800],@"cache subset not added to input");
