 Check([TFAINormalizeUsage(@{@"prompt_cache_hit_tokens":@12,@"prompt_cache_miss_tokens":@8},@"chat")[@"input"] isEqual:@20],@"DeepSeek input fallback");
 Check(!TFAINormalizeUsage(@{@"prompt_tokens":@YES,@"completion_tokens":@(-1),@"total_tokens":@1.2},@"chat").count,@"invalid counts rejected");
 NSURL *dir=[NSURL fileURLWithPath:[NSTemporaryDirectory() stringByAppendingPathComponent:NSUUID.UUID.UUIDString] isDirectory:YES];TFAIUsageStore *s=[[TFAIUsageStore alloc]initWithDirectory:dir];NSDictionary *c=@{@"id":@"c",@"name":@"Fixture",@"model":@"model-A",@"protocol":@"chat",@"secret":@"DO_NOT_STORE",@"baseURL":@"https://not-stored.invalid"};NSString *a=NSUUID.UUID.UUIDString;
 [s begin:a project:@"p" session:@"s1" connection:c wire:@"chat"];[s update:a usage:@{@"prompt_tokens":@1000}];[s update:a usage:@{@"completion_tokens":@100,@"prompt_tokens_details":@{@"cached_tokens":@800}}];[s update:a usage:@{@"completion_tokens":@100}];[s finish:a status:@"completed"];[s update:a usage:@{@"completion_tokens":@9999}];
 NSArray *r=Read(s);Check(r.count==1,@"one request despite repeated stream usage");Check([r[0][@"counts"][@"total"] isEqual:@1100],@"partial counters merged once");Check([r[0][@"status"] isEqual:@"completed"],@"completed status");Check(![[r description] containsString:@"DO_NOT_STORE"]&&![[r description] containsString:@"not-stored.invalid"],@"no secret endpoint or prompt in ledger");
 NSString *b=NSUUID.UUID.UUIDString;[s begin:b project:@"p" session:@"s1" connection:@{@"model":@"model-B"} wire:@"anthropic"];[s update:b usage:@{@"input_tokens":@200,@"cache_read_input_tokens":@100,@"cache_creation_input_tokens":@50}];[s update:b usage:@{@"output_tokens":@30}];[s finish:b status:@"stopped"];
 r=Read(s);NSDictionary *t=TFAIUsageTotals(r);Check([t[@"input"] isEqual:@1350]&&[t[@"output"] isEqual:@130]&&[t[@"total"] isEqual:@1480],@"Anthropic cache creation and read are additional input");Check([t[@"sessions"] isEqual:@1]&&[t[@"requests"] isEqual:@2],@"session shared across model switch");Check(fabs([t[@"cacheHitRate"] doubleValue]-900.0/1350)<.00001,@"weighted cache hit rate");Check([t[@"cacheWrite"] isEqual:@50],@"cache write separate");
 NSString *g=NSUUID.UUID.UUIDString;[s begin:g project:@"p" session:@"s2" connection:c wire:@"gemini"];[s update:g usage:@{@"promptTokenCount":@100,@"candidatesTokenCount":@25,@"thoughtsTokenCount":@40,@"cachedContentTokenCount":@0,@"totalTokenCount":@165}];[s finish:g status:@"completed"];t=TFAIUsageTotals(Read(s));Check([t[@"output"] isEqual:@195]&&[t[@"reasoning"] isEqual:@40],@"Gemini output includes thought tokens once");
 NSString *missing=NSUUID.UUID.UUIDString;[s begin:missing project:@"p" session:@"s2" connection:c wire:@"chat"];[s finish:missing status:@"failed"];t=TFAIUsageTotals(Read(s));Check([t[@"requests"] isEqual:@4]&&[t[@"complete"] isEqual:@3]&&[t[@"cacheKnown"] isEqual:@3],@"missing usage recorded without fake zeros");
 NSString *interrupted=NSUUID.UUID.UUIDString;[s begin:interrupted project:@"p" session:@"s3" connection:c wire:@"chat"];[s update:interrupted usage:@{@"prompt_tokens":@40,@"completion_tokens":@0}];Read(s);s=[[TFAIUsageStore alloc]initWithDirectory:dir];r=Read(s);BOOL recovered=NO;for(NSDictionary *row in r)if([row[@"id"] isEqual:interrupted])recovered=[row[@"status"] isEqual:@"interrupted"]&&[row[@"counts"][@"input"] isEqual:@40];Check(recovered,@"restart retains counters and identifies interrupted attempt");
 t=TFAIUsageTotals(@[@{@"wire":@"chat",@"counts":@{@"input":@10,@"cachedInput":@50}}]);Check(!t[@"cachedInput"]&&!t[@"cacheHitRate"],@"invalid cache greater than input rejected");
 t=TFAIUsageTotals(@[@{@"counts":@{@"input":@100,@"output":@10}},@{@"counts":@{@"input":@10,@"cachedInput":@5}}]);Check([t[@"cacheHitRate"] doubleValue]==.5&&[t[@"cacheKnown"] isEqual:@1],@"missing cache fields excluded from denominator");
 [@"broken" writeToURL:[dir URLByAppendingPathComponent:@"damaged.json"] atomically:YES encoding:NSUTF8StringEncoding error:nil];Check(Read(s).count==5,@"damaged record skipped");[s begin:@"../../bad" project:@"p" session:@"s" connection:c wire:@"chat"];Check(Read(s).count==5,@"request ID cannot traverse paths");
 [NSFileManager.defaultManager removeItemAtURL:dir error:nil];printf("Usage: %d checks passed\n",checks);return 0;
}}
